import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart' as p;
import 'package:intl/intl.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';
import 'dart:math';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final db = await openDatabase(p.join(await getDatabasesPath(), 'mr_vision.db'), version: 1, onCreate: (d,v) async {
    await d.execute('CREATE TABLE products(id INTEGER PRIMARY KEY, code TEXT UNIQUE, name TEXT, price REAL, qty INTEGER, gst REAL)');
    await d.execute('CREATE TABLE clients(id INTEGER PRIMARY KEY, name TEXT, phone TEXT, address TEXT)');
    await d.execute('CREATE TABLE sales(id INTEGER PRIMARY KEY, number TEXT UNIQUE, date TEXT, customer TEXT, total REAL)');
    await d.execute('CREATE TABLE lines(id INTEGER PRIMARY KEY, sale INTEGER, name TEXT, qty INTEGER, price REAL, gst REAL)');
  });
  runApp(ERP(db:db));
}
String money(num n) => NumberFormat.currency(locale:'en_IN',symbol:'₹').format(n);
class ERP extends StatefulWidget {
  final Database db; const ERP({super.key,required this.db});
  @override State<ERP> createState()=>_ERPState();
}
class _ERPState extends State<ERP> {
  bool dark=false;
  @override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'MR Vision Tech',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff315ce8)),scaffoldBackgroundColor:const Color(0xfff4f6fb)),darkTheme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff315ce8),brightness:Brightness.dark)),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Home(db:widget.db,dark:dark,toggle:()=>setState(()=>dark=!dark)));
}
class Home extends StatefulWidget {
 final Database db; final bool dark; final VoidCallback toggle;
 const Home({super.key,required this.db,required this.dark,required this.toggle});
 @override State<Home> createState()=>_HomeState();
}
class _HomeState extends State<Home> {
 int tab=0; String search=''; bool busy=false; int? client;
 List<Map<String,Object?>> products=[],clients=[],sales=[]; final Map<int,int> cart={};
 @override void initState(){super.initState(); refresh();}
 Future<void> refresh() async {final a=await widget.db.query('products',orderBy:'name');final b=await widget.db.query('clients',orderBy:'name');final c=await widget.db.query('sales',orderBy:'id DESC');if(mounted)setState((){products=a;clients=b;sales=c;});}
 void go(int i)=>setState((){tab=i;search='';});
 void message(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 double total(Map<String,Object?> r,int q)=>(r['price'] as num).toDouble()*q*(1+(r['gst'] as num)/100);
 double get cartTotal=>products.fold(0.0,(s,r)=>s+total(r,cart[r['id']]??0));
 Widget field(String label,TextEditingController c,{bool numeric=false})=>Padding(padding:const EdgeInsets.only(bottom:14),child:TextField(controller:c,keyboardType:numeric?const TextInputType.numberWithOptions(decimal:true):TextInputType.text,decoration:InputDecoration(labelText:label,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14)))));
 Future<void> edit(bool product) async {
 final cs=List.generate(product?5:3,(_)=>TextEditingController());
 final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(product?'Add product':'Add customer'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:List.generate(cs.length,(i)=>field((product?['Item code','Product name','Price before GST','Stock quantity','GST %']:['Name','Phone','Address'])[i],cs[i],numeric:product&&i>=2)))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Save'))]));
 final v=cs.map((c)=>c.text.trim()).toList();for(final c in cs){c.dispose();}if(ok!=true)return;
 try{if(product){final price=double.tryParse(v[2]);final qty=int.tryParse(v[3]);final gst=double.tryParse(v[4]);if(v[0].isEmpty||v[1].isEmpty||price==null||!price.isFinite||price<0||qty==null||qty<0||gst==null||!gst.isFinite||gst<0||gst>100)throw Exception('Enter valid product details');await widget.db.insert('products',{'code':v[0],'name':v[1],'price':price,'qty':qty,'gst':gst});}else{if(v[0].isEmpty)throw Exception('Name is required');await widget.db.insert('clients',{'name':v[0],'phone':v[1],'address':v[2]});}await refresh();message('Saved successfully');}catch(e){message('Could not save: $e');}
 }
 Future<void> checkout() async {if(busy||!cart.values.any((q)=>q>0))return;setState(()=>busy=true);try{final number='MR-${DateFormat('ddMMyy').format(DateTime.now())}-${Random.secure().nextInt(0x1000000).toRadixString(16).padLeft(6,'0').toUpperCase()}';await widget.db.transaction((tx) async {final id=await tx.insert('sales',{'number':number,'date':DateTime.now().toIso8601String(),'customer':clients.firstWhere((r)=>r['id']==client,orElse:()=>{'name':'Walk-in'})['name'],'total':cartTotal});for(final r in products){final q=cart[r['id']]??0;if(q==0)continue;final changed=await tx.rawUpdate('UPDATE products SET qty=qty-? WHERE id=? AND qty>=?',[q,r['id'],q]);if(changed!=1)throw Exception('Insufficient stock');await tx.insert('lines',{'sale':id,'name':r['name'],'qty':q,'price':r['price'],'gst':r['gst']});}});cart.clear();await refresh();if(mounted){go(3);message('Invoice saved');}}catch(e){message('Sale failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> invoice(Map<String,Object?> r) async {try{final lines=await widget.db.query('lines',where:'sale=?',whereArgs:[r['id']]);final doc=pw.Document();doc.addPage(pw.MultiPage(build:(_)=>[pw.Text('MR Vision Tech',style:pw.TextStyle(fontSize:24,fontWeight:pw.FontWeight.bold)),pw.Text('Invoice ${r['number']}'),pw.Text('${r['date']}  |  ${r['customer']}'),pw.SizedBox(height:20),pw.TableHelper.fromTextArray(headers:['Item','Qty','Rate','GST %','Amount'],data:lines.map((l)=>[l['name'],l['qty'],l['price'],l['gst'],total(l,l['qty'] as int).toStringAsFixed(2)]).toList()),pw.SizedBox(height:20),pw.Text('Total: INR ${(r['total'] as num).toStringAsFixed(2)}')]));await Printing.sharePdf(bytes:await doc.save(),filename:'${r['number']}.pdf');}catch(e){message('PDF error: $e');}}
 Widget heading(String title,String sub)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:5),Text(sub,style:Theme.of(context).textTheme.bodyMedium)]);
 Widget metric(String title,String value,IconData icon,Color color)=>Card(elevation:0,child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[CircleAvatar(backgroundColor:color.withOpacity(.13),foregroundColor:color,child:Icon(icon)),Text(title),FittedBox(fit:BoxFit.scaleDown,child:Text(value,style:const TextStyle(fontSize:23,fontWeight:FontWeight.bold)))])));
 Widget saleTile(Map<String,Object?> r)=>Card(elevation:0,child:ListTile(leading:const CircleAvatar(child:Icon(Icons.receipt_long_outlined)),title:Text('${r['number']}'),subtitle:Text('${r['customer']} • ${DateFormat('dd MMM, HH:mm').format(DateTime.parse(r['date'] as String))}'),trailing:Text(money(r['total'] as num),style:const TextStyle(fontWeight:FontWeight.bold)),onTap:()=>invoice(r)));
 List<Widget> dashboard(){final today=DateTime.now().toIso8601String().substring(0,10);final daily=sales.where((r)=>(r['date'] as String).startsWith(today));return [heading('Business overview','Your business, at a glance'),const SizedBox(height:18),Container(padding:const EdgeInsets.all(24),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff14285a),Color(0xff315ce8)]),borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('TODAY’S REVENUE',style:TextStyle(color:Colors.white70,letterSpacing:1.5)),const SizedBox(height:12),Text(money(daily.fold<num>(0,(s,r)=>s+(r['total'] as num))),style:const TextStyle(color:Colors.white,fontSize:32,fontWeight:FontWeight.bold)),const SizedBox(height:16),FilledButton.tonalIcon(onPressed:()=>go(2),icon:const Icon(Icons.add),label:const Text('New invoice'))])),const SizedBox(height:12),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),childAspectRatio:1.2,children:[metric('Invoices today','${daily.length}',Icons.receipt_long,Colors.blue),metric('Products','${products.length}',Icons.inventory_2,Colors.deepPurple),metric('Low stock','${products.where((r)=>(r['qty'] as int)<=5).length}',Icons.warning_amber,Colors.orange),metric('Customers','${clients.length}',Icons.people,Colors.teal)]),const SizedBox(height:20),Text('Recent invoices',style:Theme.of(context).textTheme.titleLarge),if(sales.isEmpty)const Padding(padding:EdgeInsets.all(20),child:Text('No invoices yet')),...sales.take(5).map(saleTile)];}
 Widget searchBox()=>TextField(key:ValueKey(tab),onChanged:(s)=>setState(()=>search=s.toLowerCase()),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Search records',filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none)));
 List<Widget> records(bool product){final rows=product?products:clients;final filtered=rows.where((r)=>r.values.join(' ').toLowerCase().contains(search));return [heading(product?'Inventory':'Customers',product?'Manage products and stock':'Manage customer relationships'),const SizedBox(height:16),searchBox(),const SizedBox(height:12),FilledButton.icon(onPressed:()=>edit(product),icon:const Icon(Icons.add),label:Text(product?'Add product':'Add customer')),if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(32),child:Center(child:Text('No records found'))),...filtered.map((r)=>Card(elevation:0,child:ListTile(leading:CircleAvatar(child:Icon(product?Icons.inventory_2_outlined:Icons.person_outline)),title:Text('${r['name']}'),subtitle:Text(product?'${r['code']} • ${r['qty']} in stock':'${r['phone']} • ${r['address']}'),trailing:product?Text(money(r['price'] as num)):null)))];}
 List<Widget> pos()=>[heading('New sale','Select products and review your cart'),const SizedBox(height:16),DropdownButtonFormField<int>(value:client,decoration:const InputDecoration(labelText:'Customer',border:OutlineInputBorder()),items:[const DropdownMenuItem<int>(value:null,child:Text('Walk-in customer')),...clients.map((r)=>DropdownMenuItem<int>(value:r['id'] as int,child:Text('${r['name']}')))],onChanged:busy?null:(v)=>setState(()=>client=v)),const SizedBox(height:12),searchBox(),if(products.isEmpty)TextButton(onPressed:()=>go(1),child:const Text('Add products first')),...products.where((r)=>r.values.join(' ').toLowerCase().contains(search)).map((r){final id=r['id'] as int;final q=cart[id]??0;return Card(elevation:0,child:ListTile(title:Text('${r['name']}'),subtitle:Text('${money(r['price'] as num)} + ${r['gst']}% GST'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:busy||q==0?null:()=>setState(()=>cart[id]=q-1),icon:const Icon(Icons.remove_circle_outline)),Text('$q'),IconButton(onPressed:busy||q>=(r['qty'] as int)?null:()=>setState(()=>cart[id]=q+1),icon:const Icon(Icons.add_circle))])));}),const SizedBox(height:16),Text('Cart total  ${money(cartTotal)}',style:Theme.of(context).textTheme.titleLarge),FilledButton.icon(onPressed:busy||!cart.values.any((q)=>q>0)?null:checkout,icon:const Icon(Icons.check),label:const Text('Save invoice'))];
 @override Widget build(BuildContext context){final pages=[dashboard,()=>records(true),pos,()=>[heading('Invoices','Tap an invoice to share its PDF'),...sales.map(saleTile)],()=>[heading('Settings','MR Vision Tech'),SwitchListTile(title:const Text('Dark mode'),value:widget.dark,onChanged:(_)=>widget.toggle()),ListTile(leading:const Icon(Icons.info_outline),title:const Text('About ERP'),subtitle:const Text('MR Vision Tech • Offline edition 1.0.0'))],()=>records(false)];return Scaffold(appBar:AppBar(title:const Row(children:[CircleAvatar(child:Icon(Icons.bolt)),SizedBox(width:12),Text('MR Vision Tech',style:TextStyle(fontWeight:FontWeight.bold))]),actions:[IconButton(onPressed:()=>go(5),icon:const Icon(Icons.people_outline),tooltip:'Customers')]),body:SafeArea(child:ListView(key:ValueKey(tab),padding:const EdgeInsets.all(16),children:pages[tab]())),bottomNavigationBar:NavigationBar(selectedIndex:tab==5?4:tab,onDestinationSelected:go,destinations:const [NavigationDestination(icon:Icon(Icons.dashboard_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.inventory_2_outlined),label:'Stock'),NavigationDestination(icon:Icon(Icons.shopping_cart_outlined),label:'POS'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),label:'Sales'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'More')]));}
}
